package com.example.doctoolkit.network;
import android.content.*; import android.net.Uri; import java.io.*; import okhttp3.*;
public class ProgressRequestBody extends RequestBody { public interface Listener{void onProgress(int pct);} private final Context ctx; private final Uri uri; private final MediaType type; private final Listener listener; public ProgressRequestBody(Context c, Uri u, String mt, Listener l){ctx=c;uri=u;type=MediaType.parse(mt);listener=l;} public MediaType contentType(){return type;} public long contentLength(){try{return ctx.getContentResolver().openFileDescriptor(uri,"r").getStatSize();}catch(Exception e){return -1;}} public void writeTo(okio.BufferedSink sink)throws IOException{ long total=contentLength(), sent=0; try(InputStream in=ctx.getContentResolver().openInputStream(uri)){byte[] b=new byte[8192]; int n; while((n=in.read(b))!=-1){sink.write(b,0,n); sent+=n; if(total>0&&listener!=null) listener.onProgress((int)(sent*100/total));}} } }
